-- Agenda alert emails: when a new or revised agenda has land-use items matching a watch, extract-agendas emails
-- the digest list (DIGEST_TO). Revised agendas are found by re-fetching upcoming agendas and comparing a hash.

alter table public.meetings
  add column if not exists agenda_hash text,                 -- sha-256 of the agenda file (PDF bytes, or the text of an HTML agenda)
  add column if not exists agenda_rechecked_at timestamptz,  -- last time the posted agenda was re-fetched to look for a revision
  add column if not exists agenda_revised_at timestamptz,    -- when a revision was found and re-read
  add column if not exists agenda_previous_items jsonb,      -- agenda_items before the latest revision, for "added / removed"
  add column if not exists agenda_alerted_at timestamptz;    -- when the current read was checked against watches (and emailed if it matched)

-- Agendas already read are treated as alerted, so turning this on doesn't email the backlog.
update public.meetings set agenda_alerted_at = now()
  where agenda_read_at is not null and agenda_alerted_at is null;

